// 独立恢复oracle各物理状态的C域typed读取与键序保全；这不是native完整命令续跑声明。
#include "background_support.hpp"
int main(int argc,char** argv){assert(argc>=3);auto input=read_file(argv[1]);auto data=input.find("catalog");if(!data)data=input.find("data");assert(data);auto common=std::make_shared<const CommonCatalog>(checked(decode_common_catalog(*data)));auto military_catalog=checked(decode_military_catalog(*data,boundary::get_string(read_file(argv[2]),"scenario_id","state")));auto interaction_catalog=checked(decode_interaction_catalog(*data,common));Integer states=0,sessions=0;
    for(int i=2;i<argc;++i){auto source=read_file(argv[i]);auto m=checked(decode_military_seed(source));auto in=checked(decode_interaction_seed(source));compare_fragment(source,checked(export_military_state(m)));compare_fragment(source,checked(export_interaction_state(in)));sessions+=in.interactions.size();CodecVisitor::Buffer bytes;CodecVisitor write(bytes);require(visit_interaction_checkpoint(write,in));require(write.finish());InteractionState restored;CodecVisitor read(static_cast<const CodecVisitor::Buffer&>(bytes));require(visit_interaction_checkpoint(read,restored));require(read.finish());equal(checked(export_interaction_state(in)),checked(export_interaction_state(restored)),argv[i]);++states;}
    std::cout<<"background_recovery: PASS ("<<states<<" frozen recovery state files, "<<sessions<<" dialogue session snapshots; exact values/types/record dictionary order)\n";
}
